{
  "system": {
    "name": "enterprise-core-platform",
    "environment": "production",
    "version": "2.4.0",
    "datacenter": "us-east-1",
    "cluster_id": "cls-legacy-001",
    "replicas": 3,
    "maintenance_window": "Sun 02:00-04:00 UTC"
  },
  "runtime": {
    "engine": "node20",
    "memory_limit_mb": 4096,
    "cpu_cores": 2.0,
    "garbage_collector": "default",
    "concurrency_limit": 500
  },
  "networking": {
    "domain": "api.enterprise.internal",
    "port": 8080,
    "ssl_termination": "edge",
    "tls_min_version": "1.2",
    "keep_alive_timeout_ms": 65000,
    "headers_timeout_ms": 66000,
    "cors": {
      "enabled": true,
      "allow_credentials": true,
      "allowed_origins": [
        "https://console.enterprise.com",
        "https://admin.enterprise.com"
      ],
      "max_age_seconds": 86400
    }
  },
  "database": {
    "primary": {
      "driver": "postgres",
      "host": "aurora-pg-primary.internal",
      "port": 5432,
      "database_name": "enterprise_db",
      "pool": {
        "min": 5,
        "max": 20,
        "idle_timeout_ms": 10000,
        "acquire_timeout_ms": 30000
      },
      "ssl_mode": "require"
    },
    "replicas": [
      {
        "host": "aurora-pg-read-01.internal",
        "port": 5432,
        "weight": 50
      },
      {
        "host": "aurora-pg-read-02.internal",
        "port": 5432,
        "weight": 50
      }
    ]
  },
  "caching": {
    "redis": {
      "cluster_mode": true,
      "nodes": [
        "redis-node-01.internal:6379",
        "redis-node-02.internal:6379",
        "redis-node-03.internal:6379"
      ],
      "default_ttl_seconds": 3600,
      "max_memory_policy": "volatile-lru",
      "key_prefix": "app_v2:"
    }
  },
  "security": {
    "auth_provider": "internal_oauth2",
    "jwt": {
      "issuer": "https://auth.enterprise.com",
      "audience": "enterprise-apis",
      "algorithm": "RS256",
      "token_lifetime_minutes": 60,
      "refresh_token_lifetime_days": 14
    },
    "rate_limiting": {
      "enabled": true,
      "strategy": "token_bucket",
      "burst_capacity": 100,
      "refill_rate_per_sec": 20,
      "ip_whitelist": [
        "10.0.0.0/8",
        "192.168.0.0/16"
      ]
    },
    "waf": {
      "enabled": true,
      "mode": "blocking",
      "block_sqli": true,
      "block_xss": true
    }
  },
  "messaging": {
    "kafka": {
      "brokers": [
        "kafka-01.internal:9092",
        "kafka-02.internal:9092",
        "kafka-03.internal:9092"
      ],
      "client_id": "core-producer",
      "acks": "all",
      "compression": "gzip",
      "topics": {
        "user_events": "events.users.v1",
        "order_events": "events.orders.v1",
        "audit_logs": "logs.audit.v1"
      }
    }
  },
  "storage": {
    "provider": "aws_s3",
    "bucket_name": "enterprise-assets-prod",
    "region": "us-east-1",
    "encryption": "AES256",
    "accelerate": false,
    "max_upload_size_mb": 50
  },
  "feature_flags": {
    "enable_ai_agent": false,
    "enable_dark_mode": true,
    "enable_new_checkout_flow": false,
    "enable_vector_search": false,
    "max_export_rows": 10000,
    "experimental_graph_engine": false
  },
  "integrations": {
    "payment_gateway": {
      "provider": "stripe",
      "webhook_tolerance_sec": 300,
      "auto_retry": true,
      "max_retries": 3
    },
    "email_service": {
      "provider": "sendgrid",
      "from_address": "no-reply@enterprise.com",
      "track_opens": true
    },
    "telemetry": {
      "datadog": {
        "enabled": true,
        "sample_rate": 0.2
      }
    }
  },
  "logging": {
    "level": "info",
    "format": "json",
    "include_caller_info": false,
    "redact_keys": [
      "password",
      "secret",
      "token",
      "credit_card",
      "cvv"
    ]
  },
  "monitoring": {
    "metrics_port": 9090,
    "prometheus_endpoint": "/metrics",
    "health_check_path": "/healthz",
    "liveness_probe": {
      "initial_delay_seconds": 15,
      "period_seconds": 10,
      "timeout_seconds": 2
    },
    "readiness_probe": {
      "initial_delay_seconds": 5,
      "period_seconds": 5,
      "timeout_seconds": 1
    },
    "alerts": {
      "slack_channel": "#devops-alerts",
      "pagerduty_service_key": "PD-OLD-CORE-KEY-1122"
    }
  }
}

